  CONSTRAINT `fk_fk_status` FOREIGN KEY (`status_kembali_key`) REFERENCES `dim_status_kembali` (`status_kembali_key`),
  CONSTRAINT `fk_fk_waktu` FOREIGN KEY (`waktu_jatuh_tempo_key`) REFERENCES `dim_waktu` (`waktu_key`)
